def solve(N, Q, A, B):
    max_servings = 0
    for servings_A in range(10**6 + 1):
        for servings_B in range(10**6 + 1):
            valid = True
            for i in range(N):
                if servings_A * A[i] + servings_B * B[i] > Q[i]:
                    valid = False
                    break
            if valid:
                max_servings = max(max_servings, servings_A + servings_B)
    return max_servings

n = int(input())
q = list(map(int, input().split()))
a = list(map(int, input().split()))
b = list(map(int, input().split()))

print(solve(n, q, a, b))
